DECLARE
    v_log_id   NUMBER;
    v_prj_id   NUMBER;
    v_exists   NUMBER;
BEGIN
    SELECT COUNT(*) INTO v_exists FROM XSUP.MSDWHTKD_WRK WHERE CLIENT_KEY = 'XLSXIMPORT:RC:19C TEST#2';
