DECLARE
    v_log_id   NUMBER;
    v_prj_id   NUMBER;
    v_exists   NUMBER;
BEGIN
    SELECT COUNT(*) INTO v_exists FROM XSUP.MSDWHTKD_WRK WHERE CLIENT_KEY = 'XLSXIMPORT:RC:11274';
    IF v_exists = 0 THEN
    v_log_id := XSUP.SEQ_MSDWHTKD_WRK.NEXTVAL;
    INSERT INTO XSUP.MSDWHTKD_WRK (
        LOG_ID, CLIENT_KEY, SITE_CD, WRITE_STATUS, TICKET_NO, TICKET_CONTENTS, MENU_NM,
