DECLARE
    v_log_id   NUMBER;
    v_prj_id   NUMBER;
    v_exists   NUMBER;
BEGIN
    SELECT COUNT(*) INTO v_exists FROM XSUP.MSDWHTKD_WRK WHERE CLIENT_KEY = 'XLSXIMPORT:RC:12711';
    IF v_exists = 0 THEN
    v_log_id := XSUP.SEQ_MSDWHTKD_WRK.NEXTVAL;
    INSERT INTO XSUP.MSDWHTKD_WRK (
        LOG_ID, CLIENT_KEY, SITE_CD, WRITE_STATUS, TICKET_NO, TICKET_CONTENTS, MENU_NM,
        PERSON_IN_CHARGE, LOCAL_PC_IP, START_DT, END_DT, DEPLOY_STATUS, DEPLOY_DT,
        WORK_COMMENT, CHANGESET_ID, AUTHOR_NM, TEAM_NM, CHANGED_FILE_COUNT,
